from app.database import db

class Solution:
    def __init__(self, solution_id=None, problem_id=None, user_id=None, code=None, status=None):
        self.solution_id = solution_id
        self.problem_id = problem_id
        self.user_id = user_id
        self.code = code
        self.status = status

    def to_dict(self):
        return {
